{
  "pages": 2,
  "messages": 30,
  "warnings": [],
  "limitations": [
    "Committed history, not live token events or every workflow broadcast.",
    "Inspect raw page/tool fields for truncation. Missing evidence stays explicitly missing."
  ]
}

{
  "id": "bugfix",
  "label": "Bugfix",
  "description": "Reproduce a wrong behavior, fix the smallest cause, and prove the regression is covered.",
  "when_to_use": "Use when existing observable behavior is incorrect and should be corrected.",
  "steps": [
    {
      "key": "reproduce",
      "label": "Reproduce the failure",
      "phase": "red",
      "guidance": "Capture the wrong behavior with a failing test, fixture, command, or clear manual reproduction."
    },
    {
      "key": "diagnose",
      "label": "Diagnose root cause",
      "phase": "analysis",
      "guidance": "Trace the failure to the smallest responsible code path and check for related cases."
    },
    {
      "key": "fix",
      "label": "Implement the fix",
      "phase": "green",
      "guidance": "Make the minimal code change that addresses the root cause while preserving intended behavior."
    },
    {
      "key": "regression",
      "label": "Prove regression coverage",
      "phase": "verify",
      "guidance": "Run the reproduction and relevant surrounding checks on the final artifact. Then inspect the final changes for unintended behavior, compatibility or preservation problems, and unrelated edits. Use an available diff or compare the relevant before-and-after content; version-control tooling is not required. Record the results and any unreviewed areas before completing this step."
    },
    {
      "key": "handoff",
      "label": "Handoff",
      "phase": "handoff",
      "guidance": "Before marking this step complete, provide the handoff: summarize the defect, fix, checks actually run and their results, changed artifacts, and remaining risk or next action. Distinguish successful checks from unavailable or skipped validation."
    }
  ],
  "guards": []
}

{
  "acceptance": [
    "Separates touching intervals, merges true overlaps transitively, handles empty/unsorted/nested/duplicate/negative cases.",
    "Preserves input and API; worker adds meaningful regression coverage."
  ],
  "critical": [
    "Touching bookings still merge, overlapping bookings fail to merge, or input is mutated."
  ],
  "docs_semantic_fallback": "Frozen documentation parser mismatches need direct semantic review, not automatic failure."
}
